/**
 * scripts/build-checkout-cart-html.mjs
 * ---------------------------------------------------------------------------
 * Writes src/webflow/checkout-cart.html from src/js/checkout-cart/markup.js.
 *
 *   node scripts/build-checkout-cart-html.mjs
 *
 * This file is now OPTIONAL. checkout-cart.js renders the same markup in the
 * browser when the page does not supply it, so a Webflow page needs only:
 *
 *   <div data-checkout></div>
 *   <script src="https://bvc-app-uat.vercel.app/js/checkout-cart.js" defer></script>
 *
 * The generated file is kept for pages that already paste markup, and as a
 * readable reference for what the runtime produces. Both come from the same
 * renderer, so they cannot disagree.
 *
 * Node built-ins only — no dependencies, no bundler.
 */

import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { renderFormInner, fields, steps } from '../src/js/checkout-cart/markup.js';

const here = dirname(fileURLToPath(import.meta.url));
const OUT_DIR = join(here, '..', 'src', 'webflow');
const OUT_FILE = join(OUT_DIR, 'checkout-cart.html');
const ASSET_ORIGIN = 'https://bvc-app-uat.vercel.app';

const banner = `<!--
  checkout-cart.html — Generated by scripts/build-checkout-cart-html.mjs. DO NOT EDIT BY HAND.
  Edit src/js/checkout-cart/content.js and re-run the generator instead.

  YOU PROBABLY DO NOT NEED THIS FILE. checkout-cart.js renders the same markup at
  runtime, so a Webflow page only needs an empty container and the script tag:

    <div data-checkout></div>

  Page settings → Before </body>:
    <link rel="stylesheet" href="${ASSET_ORIGIN}/css/checkout-cart.css">
    <script src="${ASSET_ORIGIN}/js/checkout-cart.js" defer></script>
    <script src="${ASSET_ORIGIN}/js/checkout.js" defer></script>

  Pasting the markup below still works and takes precedence — the runtime leaves
  markup alone when it finds it. But then every change to a field or an option list
  needs a re-paste, and a stale paste fails silently. Prefer the empty container.
-->
`;

async function build() {
  await mkdir(OUT_DIR, { recursive: true });
  await writeFile(OUT_FILE, `${banner}<div data-checkout>\n${renderFormInner()}\n</div>\n`, 'utf8');
  console.log(`✓ checkout-cart.html written (${fields.length} fields, ${steps.length} steps)`);
  console.log(`  → ${OUT_FILE}`);
}

build().catch((error) => {
  console.error('Build failed:', error);
  process.exit(1);
});
